use super::prelude::*;

/// GamblersBrew — discard any number of chosen hand cards, then draw
/// that many. C# GamblersBrew.OnUse:
/// `CardSelectCmd.FromHandForDiscard(prefs(0, 999999999))` →
/// `CardCmd.DiscardAndDraw(list, list.Count)` — a player choice
/// (consuming no RunRngSet stream for the *pick*). Bead `sts2-rs-1xmxp`
/// replaces the prior uniform-random subset (the `NOTE(sts2-rs-sr3ql)`
/// legacy-rng caveat is now resolved). Open a `DiscardFromHandAndDraw`
/// choice over the whole hand (min 0, max = hand size, skippable); the
/// `sts2-rs-enwwr` fan-out enumerates the selections and the resolver
/// discards each chosen card then draws one per discard (off the shuffle
/// RunRng stream). Empty hand ⇒ no-op.
pub(crate) fn drink_gamblers_brew(state: &mut CombatState, _target: Option<u8>) -> EffectResult {
    if state.player.hand.is_empty() {
        return EffectResult::Resolved;
    }
    let options: Vec<sts2_core::ChoiceOption> = state
        .player
        .hand
        .iter()
        .map(|&uid| {
            let idx = uid.0.get() as usize - 1;
            sts2_core::ChoiceOption {
                card_id: state.cards[idx].card_id,
                upgraded: state.cards[idx].upgraded,
                card_uid: Some(uid),
                source_pile: Some(sts2_core::cards::PileKind::Hand),
            }
        })
        .collect();
    let max = u8::try_from(options.len()).unwrap_or(u8::MAX);
    state.request_card_choice(
        sts2_core::ChoiceKind::DiscardFromHandAndDraw,
        options,
        0,
        max,
        true,
    );
    EffectResult::Resolved
}
